search.query:
`DC-index` (sourcetype="WinEventLog:Security" OR source="WinEventLog:Security") ( EventCode=5136 AND (Class="group" OR ObjectType="Group") ) | search $search_filter$ | eval ObjectDN = coalesce(DN, TargetObject, ObjectName) | rex field=DN "(?i)cn=(?<GroupName>[^,]+)" | eval AdminUser = SubjectUserName | eval Computer = ComputerName
| lookup cs_obj_change_eventcodes.csv EventCode OUTPUT signature as DefaultSignature
| rex field=Message "(?i)AttributeLDAPDisplayName\s*:\s*(?<AttrName>[^,
]+)" | rex field=Message "(?i)OldValue\s*:\s*(?<OldVal>[^,
]+)" | rex field=Message "(?i)NewValue\s*:\s*(?<NewVal>[^,
]+)" | rex field=Message "(?i)AttributeValue\s*:\s*(?<AttrValue>[^,
]+)" | rex field=Message "(?i)groupType\s*:?\s+(?<GroupTypeCode>-?\d+)"
| rex field=Message "(?i)Operation:\s*Type:?\s*(?<operation_type>[^,
]+)" | rex field=Message "(?i)Attribute:\s*(?<Attributes>[\s\S]*?)(?=
\s*
\w+:|\z)" | rex field=Attributes mode=sed "s/Syntax \(OID\):[^
]*
//g" | eval Attributes=replace(Attributes, "
", ", ") | eval Attributes=replace(Attributes, "	", "") | eval Attributes=replace(Attributes, "\s+", " ")
| eval RawGroupType = coalesce(AttrValue, GroupTypeCode) | lookup cs_obj_group_details.csv groupType as RawGroupType OUTPUT groupType_Name as Group_Type_Full, MSADGroupType as Group_Type, MSADGroupClass as Group_Class
| eval Group_Type = case( EventCode IN (4737), "Global Security", EventCode IN (4735), "Local Security", EventCode IN (4745), "Local Distribution", EventCode IN (4750), "Global Distribution", EventCode IN (4755), "Universal Security", EventCode IN (4760), "Universal Distribution", EventCode IN (4764), "change security enabled,disabled", 1=1, "Unknown" ) | eval Group_Class = case( EventCode IN (4737,4735,4755), "Security", EventCode IN (4745,4750,4760), "Distribution", EventCode IN (4764), "change security mode", 1=1, "Unknown" )
| eval Changes = case( EventCode=5136 AND isnotnull(AttrName), "Attribute '".AttrName."' changed from '".coalesce(OldVal,"-")."' to '".coalesce(NewVal,"-")."'", isnotnull(DefaultSignature), DefaultSignature, 1=1, "Group attribute modified" ) | eval admin_logonID=Logon_ID | eval AdminUser=Subject_Account_Name | table _time, Computer, AdminUser,admin_logonID, ObjectDN, GUID,operation_type,Attributes | sort - _time
